const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '单位换算表：54 km/h → m/s' },
      { kind: 'text', payload: '换算项目' },
      { kind: 'text', payload: '已知值' },
      { kind: 'text', payload: '换算算式（除以 3.6）' },
      { kind: 'text', payload: '换算结果' },
      { kind: 'text', payload: '速度' },
      { kind: 'text', payload: '54 km/h' },
      { kind: 'text', payload: '54 ÷ 3.6' },
      { kind: 'text', payload: '15.0 m/s' },
      { kind: 'text', payload: '依据：1 m/s = 3.6 km/h，故把 km/h 换算成 m/s 要除以 3.6。' },
      { kind: 'text', payload: '计算：54 ÷ 3.6 = 15.0（结果保留三位有效数字）。' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var paths = [];
    var children = [];

    function addPath(id, commands, stroke, fill, strokeWidth) {
      var node = { type: 'path', pathId: id, stroke: stroke, fill: fill };
      if (strokeWidth) { node.strokeWidth = strokeWidth; }
      paths.push({ id: id, commands: commands });
      children.push(node);
    }

    function addLabel(id, text, x, y, size, fill, anchor) {
      children.push({
        type: 'label',
        id: id,
        text: text,
        x: x,
        y: y,
        fontSize: size,
        fill: fill,
        textAnchor: anchor || 'middle',
        dominantBaseline: 'middle'
      });
    }

    function rectCmds(x, y, w, h) {
      return visualSdk.polyline([[x, y], [x + w, y], [x + w, y + h], [x, y + h], [x, y]]);
    }

    function lineCmds(x1, y1, x2, y2) {
      return visualSdk.polyline([[x1, y1], [x2, y2]]);
    }

    var marginX = Math.round(W * 0.05);
    var tableX = marginX;
    var tableW = W - marginX * 2;
    var frac = [0.20, 0.22, 0.28, 0.30];
    var xs = [tableX];
    for (var i = 0; i < frac.length; i++) { xs.push(xs[i] + tableW * frac[i]); }

    var titleY = Math.round(H * 0.13);
    var headerTop = Math.round(H * 0.24);
    var headerH = Math.max(38, Math.round(H * 0.11));
    var rowH = Math.max(46, Math.round(H * 0.15));
    var tableBottom = headerTop + headerH + rowH;

    addPath('hdr-bg', rectCmds(tableX, headerTop, tableW, headerH), 'none', '#e8eef8');
    addPath('grid-out', rectCmds(tableX, headerTop, tableW, headerH + rowH), '#26354a', 'none', 1.4);
    addPath('grid-h', lineCmds(tableX, headerTop + headerH, xs[4], headerTop + headerH), '#26354a', 'none', 1.2);
    addPath('grid-v1', lineCmds(xs[1], headerTop, xs[1], tableBottom), '#26354a', 'none', 1.2);
    addPath('grid-v2', lineCmds(xs[2], headerTop, xs[2], tableBottom), '#26354a', 'none', 1.2);
    addPath('grid-v3', lineCmds(xs[3], headerTop, xs[3], tableBottom), '#26354a', 'none', 1.2);

    var headY = headerTop + headerH / 2;
    var bodyY = headerTop + headerH + rowH / 2;
    var headSize = Math.max(12, Math.round(W / 46));
    var bodySize = Math.max(13, Math.round(W / 42));
    var heads = ['换算项目', '已知值', '换算算式（除以 3.6）', '换算结果'];
    var bodys = ['速度', '54 km/h', '54 ÷ 3.6', '15.0 m/s'];
    for (var c = 0; c < 4; c++) {
      var cx = (xs[c] + xs[c + 1]) / 2;
      addLabel('h' + c, heads[c], cx, headY, headSize, '#1b2b45');
      addLabel('b' + c, bodys[c], cx, bodyY, bodySize, c === 3 ? '#0b6b3a' : '#1b2b45');
    }

    addLabel('title', '单位换算表：54 km/h → m/s', W / 2, titleY, Math.max(16, Math.round(W / 32)), '#12233d');

    var noteSize = Math.max(11, Math.round(W / 50));
    var noteY = tableBottom + Math.round(H * 0.10);
    addLabel('note1', '依据：1 m/s = 3.6 km/h，故把 km/h 换算成 m/s 要除以 3.6。', tableX, noteY, noteSize, '#33475f', 'start');
    addLabel('note2', '计算：54 ÷ 3.6 = 15.0（结果保留三位有效数字）。', tableX, noteY + Math.round(H * 0.075), noteSize, '#33475f', 'start');

    return {
      schemaVersion: 1,
      sceneId: 'unit-conversion-table',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
